var i=[{title:`Die Bewegungen der Hüfte`,text:`Hüftbeugung bringt den Oberschenkel zum Oberkörper hin, und Streckung führt ihn nach hinten. Das Gelenk rotiert außerdem nach innen und außen und bewegt das Bein über den Körper hinweg oder von ihm weg. Alltagsbewegungen verbinden mehrere Richtungen, ein Zehenberühren nach vorn sagt dir also nur einen Teil der Geschichte.`},{title:`Übungen zum Ausprobieren`,text:`Eine bequeme Hüftbeuger-Dehnung im Halbknien erkundet die Streckung, während du das Becken kontrolliert hältst. Sanfte 90/90-Hüftrotationen oder Rotationsübungen im Sitzen üben die Rotation, und ein gestützter seitlicher Ausfallschritt erkundet Länge und Kontrolle der Oberschenkelinnenseite (Adduktoren). Beginne langsam und halte dich an einer Stütze fest, wenn dein Gleichgewicht wackelig ist.`},{title:`Hüften bei deinen Hebungen`,text:`Kniebeugen brauchen, dass sich Hüften und Knöchel gemeinsam bewegen. Hüftbeugen brauchen Hüftbeugung mit kontrolliertem Rumpf. Bei einem Split Squat streckt sich eine Hüfte, während sich die andere beugt. Wenn sich eine tiefe Kniebeuge unangenehm anfühlt, löst ein anderer Stand, eine geringere Tiefe, eine Fersenunterlage oder eine Kniebeuge zu einem Stuhl das Problem möglicherweise schneller, als eine Dehnung zu erzwingen.`},{title:`Jede Hüfte ist anders`,text:`Form der Hüftpfanne, Trainingsgeschichte, aktuelle Kraft und Gelenkverträglichkeit beeinflussen alle deinen Bewegungsumfang. Eine Asymmetrie ist nicht automatisch ein Defekt, und dieselbe Dehnung gehört nicht in jeden Plan. Höre mit jeder Übung auf, die Einklemmen, stechenden Gelenkschmerz oder anhaltende Symptome verursacht, und gehe bei Bedarf zu einer Ärztin, einem Arzt oder einer Physiotherapeutin bzw. einem Physiotherapeuten.`},{title:`Fortschritt verfolgen`,text:`Mache ein paar gezielte Hüftübungen vor Einheiten, bei denen eine Bewegung davon profitiert. Miss den Fortschritt daran, wie sicher und flüssig sich deine Kniebeugen, Hüftbeugen und Ausfallschritte anfühlen, und lass die maximale Dehntiefe beiseite.`}];var t=[{label:`ACE 2026: Beweglichkeit gegenüber Dehnbarkeit`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`ACE-Übungsbibliothek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`ACSM-Positionspapier 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};